# -*- coding: utf-8 -*-
import re, sys, json
NAT=r'(?:كويتي|كويتية|مصري|مصرية|أردني|أردنية|سعودي|سعودية|بحريني|بحرينية|قطري|قطرية|إماراتي|إماراتية|سوري|سورية|لبناني|لبنانية|فلسطيني|فلسطينية|يمني|يمنية|عراقي|عراقية|سوداني|سودانية|هندي|هندية|باكستاني|إيراني)'
STOP=set('''المحامي المحامية المحاماة المحاميان المحامين الطالب الطالبة الطالبين المستأنف المستأنفة
المدعية المدعي عليه عليها الدكتور الأستاذ السيد السيدة بصفته بصفتها مدير إدارة السجن المركزي بموجب
الوكيل وكيل مكتب مجموعة والاستشارات القانونية  للمحاماة كان كانت يكون نجد ولما حيث وحيث وعلى إذا الذي التي وقد أنه أنها هذا هذه ذلك تلك بصورة قانونا خصمه الخصوم بإعتبار باعتبار يقدم إليها منها عليها عليه لهما هما ومن وعن وفي وأن وإذا حسبما مطالعة مدوناته تتحصل تخلص وقائع بمستشفى مستشفى الجهراء الأحمدي حولي الفروانية العاصمة مبارك الكبير صباح السالم غرناطة المرقاب الشرق القبلة الوزارة وزارة الصحة الداخلية الخارجية التربية الشئون العدل الهيئة العامة المدنية للمعلومات مدير عام وكيل الوزراء رئيس مجلس السيد السيدة إدارة الكتاب المحكمة الكلية الاستئناف التمييز جلسة بتاريخ الموافق الساعة صباحا مساء يوم بموجب صحيفة أودعت أعلنت وأعلنت قانوناً بالآتي الموضوع الطلب الطلبات ختامها القضاء إلتمس التمست إلتمست طلب طلبت المدعي المدعية المستأنف المستأنفة عليه عليها ضده النفقة الحضانة الزوجية أجرة مسكن خادمة سائق سيارة تعويض التطليق الطلاق الخلع الفرقة الأولاد الأبناء المحضون المحضونة الصغير الصغيرة الطالب الطالبة المعلن يعلن ويعلن مندوب الإعلان التنفيذ محله المختار الكائن ويقيم مخاطبا انتقلت وأعلنته كافة حقوق الأخرى العلم ولأجل جعفرية شخصية أحوال والمتضمن الله ويعلن يعلن الدعوى برفع تكليفه حافظ والمتضمن المتضمن وأعلنته الصادر بجلسة بتاريخ الموضوع درجة أمام الحكم والمحكمة المحكمة الاستئناف التطليق للضرر بناء طلب حاضنة بصفتها المرافعات القانون الشخصية الأحوال الآتي والكائن مخاطبا حافظة صورة ضوئية اختصاص الدفع بعدم'''.split())
def toks(s): return [w for w in re.split(r'[\s،,–\-/()\.:]+',s) if len(w)>=3 and re.match(r'^[ء-يٱآأإؤئ]+$',w) and w not in STOP]
def collect(t):
    names=set()
    # party names: 2-5 tokens right before "[–] <nat> الجنسية"
    for m in re.finditer(r'([ء-يٱآأإؤئ]+(?:\s+[ء-يٱآأإؤئ]+){1,4})\s*[–\-]?\s*'+NAT+r'\s+الجنسية', t):
        names.update(toks(m.group(1)))
    # lawyer names: right after المحامي/المحامية[/الدكتور/د.]  up to 4 tokens, stop at line end/delimiter
    for m in re.finditer(r'(?:المحامي(?:ة|ان|ون|ين)?|محام(?:ي|ية))\s*/?\s*(?:الدكتور|د\.?|أ\.?|الأستاذ)?\s*/?\s*([ء-يٱآأإؤئ]+(?:\s+[ء-يٱآأإؤئ]+){1,3})',t):
        names.update(toks(m.group(1)))
    return names
def redact(t):
    t=re.sub(r'[ \t]+',' ',t); t=re.sub(r'(?m)^\s*\d{5,}\s*','',t); t=re.sub(r'(?m)^\s*00\s*','',t)
    names=collect(t)
    t=re.sub(r'\(?\s*\b\d{11,12}\b\s*\)?','[رقم مدني]',t)
    t=re.sub(r'(تليفون|هاتف|موبايل|جوال|فاكس)\s*:?\s*[\d/\- ]{6,}',r'\1: [هاتف]',t)
    t=re.sub(r'(جواز\s+سفر\s+رقم)\s*\(?\s*[A-Za-z]?\s*[\dA-Za-z ]{4,20}\)?',r'\1 [رقم جواز]',t)
    t=re.sub(r'(بطاقة\s+رقم)\s*\(?\s*\d[\d ]{5,}\)?',r'\1 [رقم بطاقة]',t)
    t=re.sub(r'(?<![ء-ي\d])[A-Za-z]\s?\d{5,}\b','[رقم وثيقة]',t)
    t=re.sub(r'الرقم\s+الآلي\s+للعنوان\s*:?\s*\(?[^)\n]{0,25}\)?',r'[رقم العنوان]',t)
    ADRK=r'(?:شارع|قطعة|قطعه|القطعة|المبنى|مبنى|الدور|دور|شقة|الشقة|عمارة|بناية|منزل|جادة|ضاحية|بلوك|مجمع|برج|منطقة)'
    t=re.sub(r'(?:\(?\s*\d+\s*/?\s*\d*\s*\)?\s*[-–]\s*)?'+ADRK+r'\s*\(?\s*[\dA-Za-z]+\s*\)?(?:\s*[-–،,]?\s*'+ADRK+r'\s*\(?\s*[\dA-Za-z]+\s*\)?)*',r'[عنوان]',t)
    t=re.sub(r'\b\d{7,9}\b','[رقم]',t)
    t=re.sub(r'(?<!\d/)(?<!\d /)\b\d{1,4}\s*/\s*\d{4}\b','[رقم الدعوى]',t)
    t=re.sub(r'[–\-]?\s*'+NAT+r'\s+الجنسية','– [الجنسية]',t)
    t=re.sub(r'(الكائن(?:\s+مقره)?|والكـ?ائـ?ن|ويقيم\s+في|يعلن\s+في|ومحل[هـ]?ا?\s+المختار|محل[هـ]?ا?\s+المختار)\s*:?[^.،\n]{0,130}',r'\1 [العنوان] ',t)
    # children paren-lists in place (after cue), no token collection
    CH=r'(?:[لبو]?[إا]بن\S*|[لبو]?[إا]بنت\S*|[لبو]?بنت\S*|[لبو]?ولد\S*|أبناء\S*|أولاد\S*|بالأبناء|بالأولاد|المحضون\S*|طفل\S*|صغير\S*|رضيع\S*|وهم|وهما|هما)'
    t=re.sub(CH+r'\s*\(\s*[ء-ي]+(?:\s*[،,و]\s*[ء-ي]+){0,6}\s*\)',lambda m: re.sub(r'\(\s*[ء-ي].*\)','([أسماء المحضونين])',m.group(0)),t)
    HARD=['الصباح','الشمري','العنزى','العنزي','الهاجري','المري','المطوع','الماجد','العجمي','القلاف','الهنداوي','العوضي','قباذرد','زمانان','مالك','حمزه','شهاب','فيصل','عبدالكريم','عايض','راشد','آلاء','خليل','نوره','مبارك','سعد','سعود','حمود','عادل','حسين','زهرة','عصمت','سمير','سهيلة','عيد','مهدي','علا','مصطفى','ياسين','بشاير','عبدالله','حوراء','روان','عبدالمحسن','دانه','سلطان','عبدالعزيز']
    names.update(HARD)
    t=re.sub(r'\(\s*[ء-ي]{2,}(?:\s+[ء-ي]{2,}){0,3}\s+(مواليد|مولود|بتاريخ|من\s+مواليد)',r'( [اسم المحضون] \1',t)
    t=re.sub(r'(بالابن[ةه]?|بالإبن[ةه]?|لابن[تةه]?\S*|لإبن[تةه]?\S*)\s*\(\s*[ء-ي]+',r'\1 ([اسم المحضون]',t)
    toks_sorted=sorted([n for n in names if len(n)>=3],key=len,reverse=True)
    if toks_sorted:
        t=re.sub(r'(?<![ء-يٱآأإؤئ])(?:و|ف|ب|ل)?(?:'+'|'.join(re.escape(x) for x in toks_sorted)+r')(?![ء-يٱآأإؤئ])','[اسم]',t)
    t=re.sub(r'(\[اسم\]\s*){2,}','[اسم] ',t); t=re.sub(r'[ \t]+',' ',t); t=re.sub(r'\n{2,}','\n',t)
    return t.strip(),sorted(names)
f=sys.argv[1]; t=open(f+'.txt',encoding='utf-8').read()
r,names=redact(t); open(f+'.red.txt','w',encoding='utf-8').write(r)
print("### %s | names→[اسم]: %s"%(f,'، '.join(names)))
